-- analytics views -------------------------------------------------------

CREATE VIEW v_purchase_order_lines AS
SELECT
  line.id AS po_line_id,
  line.po_id,
  line.line_number,
  line.product_id,
  line.cases_ordered,
  line.unit_price_cents,
  line.line_total_cents,
  po.po_number,
  po.ordered_on,
  po.promised_on,
  po.status AS po_status,
  po.is_test,
  supplier.id AS supplier_id,
  supplier.name AS supplier_name,
  supplier.tier AS supplier_tier,
  warehouse.name AS warehouse_name,
  region.name AS region_name,
  product.sku,
  product.name AS product_name,
  product.case_pack_qty
FROM purchase_order_lines line
JOIN purchase_orders po ON po.id = line.po_id
JOIN suppliers supplier ON supplier.id = po.supplier_id
JOIN warehouses warehouse ON warehouse.id = po.warehouse_id
JOIN regions region ON region.id = warehouse.region_id
JOIN products product ON product.id = line.product_id;

CREATE VIEW v_shipments AS
SELECT
  shipment.id AS shipment_id,
  shipment.shipment_number,
  shipment.po_id,
  shipment.mode,
  shipment.shipped_on,
  shipment.expected_on,
  shipment.delivered_on,
  shipment.status,
  shipment.freight_cost_cents,
  shipment.goods_value_cents,
  shipment.tracking_number,
  po.po_number,
  po.ordered_on,
  po.promised_on,
  po.status AS po_status,
  po.is_test,
  supplier.id AS supplier_id,
  supplier.name AS supplier_name,
  supplier.tier AS supplier_tier,
  warehouse.name AS warehouse_name,
  region.name AS region_name,
  carrier.name AS carrier_name
FROM shipments shipment
JOIN purchase_orders po ON po.id = shipment.po_id
JOIN suppliers supplier ON supplier.id = po.supplier_id
JOIN warehouses warehouse ON warehouse.id = po.warehouse_id
JOIN regions region ON region.id = warehouse.region_id
JOIN carriers carrier ON carrier.id = shipment.carrier_id;

CREATE VIEW v_receipts AS
SELECT
  receipt.id AS receipt_id,
  receipt.shipment_id,
  receipt.po_line_id,
  receipt.received_on,
  receipt.units_received,
  receipt.units_accepted,
  receipt.qc_status,
  shipment.shipment_number,
  po.po_number,
  po.is_test,
  supplier.id AS supplier_id,
  supplier.name AS supplier_name,
  product.sku,
  product.name AS product_name,
  product.case_pack_qty,
  warehouse.name AS warehouse_name
FROM receipts receipt
JOIN shipments shipment ON shipment.id = receipt.shipment_id
JOIN purchase_orders po ON po.id = shipment.po_id
JOIN suppliers supplier ON supplier.id = po.supplier_id
JOIN purchase_order_lines line ON line.id = receipt.po_line_id
JOIN products product ON product.id = line.product_id
JOIN warehouses warehouse ON warehouse.id = po.warehouse_id;

COMMENT ON SCHEMA supply_chain IS
  'Synthetic eval fixture: inbound purchasing for an industrial distributor. Money is stored in cents (USD). Purchase orders were raised in calendar 2024 and 2025 only; the data is as of 2025-12-31.';
COMMENT ON COLUMN purchase_orders.is_test IS
  'Sandbox purchase orders raised to test the procurement integration. Excluded from reported volumes by default, together with their lines, shipments and receipts.';
COMMENT ON COLUMN products.case_pack_qty IS
  'Units (eaches) per case. Purchase-order lines order whole cases; receipts and inventory count units.';
COMMENT ON COLUMN shipments.expected_on IS
  'The carrier ETA quoted at dispatch. Not the delivery date promised on the purchase order (purchase_orders.promised_on).';
COMMENT ON COLUMN inventory_snapshots.snapshot_date IS
  'Month-end date of a point-in-time balance. Balances at different dates must not be added together.';
COMMENT ON COLUMN receipts.qc_status IS
  'Inspection outcome. PENDING receipts have not been inspected yet and accept 0 units until they are.';
COMMENT ON VIEW v_shipments IS
  'One row per shipment. warehouse_name/region_name are the receiving warehouse of the purchase order.';

COMMIT;
